def topo_sort(graph):
    visited = {}  # 0: unvisited, 1: visiting, 2: visited
    order = []

    def visit(node):
        if visited.get(node) == 1:
            return False
        if visited.get(node) == 2:
            return True

        visited[node] = 1
        for neighbor in graph.get(node, []):
            if not visit(neighbor):
                return False

        visited[node] = 2
        order.append(node)
        return True

    for node in graph:
        if visited.get(node, 0) == 0:
            if not visit(node):
                return None

    return order[::-1]
```

