def parse_query(qs):
    if not qs:
        return {}

    # Remove leading '?' if present
    if qs.startswith('?'):
        qs = qs[1:]

    # urllib.parse.parse_qs handles percent-encoding, 
    # '+' as space, and repeated keys automatically.
    # It returns a dict where every value is a list.
