def deep_get(obj, path, default=None):
    if not path:
        return obj

    parts = path.split('.')
    current = obj

    for part in parts:
        if isinstance(current, dict) and part in current:
            current = current[part]
        elif isinstance(current, list) and part.isdigit():
            idx = int(part)
            if 0 <= idx < len(current):
                current = current[idx]
            else:
                return default
        else:
            return default

    return current
