/**
 * Returns an array of unique elements from the input array, 
 * keeping the first occurrence of each unique key.
 * 
 * @param {Array} arr - The array to filter.
 * @param {Function} keyFn - A function that returns the key to check for uniqueness.
 * @returns {Array} - The array with duplicates removed.
 */
function uniqueBy(arr, keyFn) {
  const seen = new Set();
  return arr.filter((item) => {
    const key = keyFn(item);
    if (seen.has(key)) {
      return false;
    }
    seen.add(key);
    return true;
  });
}

module.exports = uniqueBy;
