function debounceCount(fn, ms) {
  let timeoutId = null;
  let args = null;
  let context = null;

  const debounced = function(...args) {
    context = this;
    args = args;
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
    timeoutId = setTimeout(() => {
      fn.apply(context, args);
      timeoutId = null;
    }, ms);
  };

  const flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      fn.apply(context, args);
      timeoutId = null;
    }
  };

  return {
    call: debounced,
    flush
  };
}

module.exports = debounceCount;
```

