function isObject(item) {
  return (item && typeof item === 'object' && !Array.isArray(item));
}

function mergeDeep(a, b) {
  const output = Array.isArray(a) ? [] : {};

  // Copy values from a
  Object.keys(a).forEach(key => {
    const value = a[key];
    if (isObject(value) && isObject(b[key])) {
      output[key] = mergeDeep(value, b[key]);
    } else {
      output[key] = value;
    }
  });

  // Copy values from b that aren't in a or are objects
  Object.keys(b).forEach(key => {
    const value = b[key];
    if (!a.hasOwnProperty(key)) {
      output[key] = value;
    } else if (isObject(value) && isObject(a[key])) {
      output[key] = mergeDeep(a[key], value);
    } else {
      output[key] = value;
    }
  });

  return output;
}

module.exports = mergeDeep;
```

