/**
 * Returns the item with the largest computed key from an array.
 * @param {Array} arr - The array to iterate over.
 * @param {Function} keyFn - A function that takes an element and returns a comparable value.
 * @returns {*} The item with the maximum key, or undefined if the array is empty.
 */
function maxBy(arr, keyFn) {
  if (!arr || arr.length === 0) {
    return undefined;
  }

  let maxItem = arr[0];
  let maxValue = keyFn(maxItem);

  for (let i = 1; i < arr.length; i++) {
    const currentItem = arr[i];
    const currentValue = keyFn(currentItem);

    if (currentValue > maxValue) {
      maxValue = currentValue;
      maxItem = currentItem;
    }
  }

  return maxItem;
}

module.exports = maxBy;
