function rotateArray(arr, k) {
  if (!Array.isArray(arr)) return [];
  const n = arr.length;
  if (n === 0) return [...arr];

  // Handle k larger than length and negative k
  let shift = ((k % n) + n) % n;

  if (shift === 0) return [...arr];

  const result = new Array(n);
  for (let i = 0; i < n; i++) {
    result[(i + shift) % n] = arr[i];
  }

  return result;
}

module.exports = rotateArray;
