import React, { useRef } from 'react';
import { View, Text, Button } from 'react-native';

const MutableValueComponent = () => {
  // useRef keeps the value persistent across renders
  // but changing it does not trigger a re-render
  const mutableValue = useRef(0);

  const handleIncrement = () => {
    mutableValue.current += 1;
    console.log('Current value (no re-render):', mutableValue.current);
  };

  return (
    <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
      <Text>The value is stored in a ref.</Text>
      <Text>Check console to see the value change without UI updates.</Text>
      <Button title="Increment Ref Value" onPress={handleIncrement} />
    </View>
  );
};

export default MutableValueComponent;
```

